package com.nigson.commerce.promotion;

import java.util.*;
import java.time.*;
import java.sql.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import tools.jackson.databind.JsonNode;

/** Owner-local persistence for immutable promotion revisions and finite campaign budgets. */
final class PromotionRepository {
 private static final java.security.SecureRandom RANDOM=new java.security.SecureRandom();
 private final JdbcTemplate jdbc; private final Clock clock;
 PromotionRepository(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
 private void family(String code){jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(r,n)->1,"promotion:"+code);}
 private PromotionValues.Rule rule(ResultSet r)throws SQLException{return new PromotionValues.Rule(r.getObject("id",UUID.class),r.getString("code"),r.getString("kind"),r.getObject("market_id",UUID.class),r.getTimestamp("starts_at").toInstant(),r.getTimestamp("ends_at").toInstant(),EventCodec.JSON.readTree(r.getString("parameters")),EventCodec.JSON.readTree(r.getString("eligibility")),r.getString("stacking_policy"),r.getBoolean("enabled"),r.getLong("revision"),r.getLong("version"));}
 private PromotionValues.Coupon coupon(ResultSet r)throws SQLException{return new PromotionValues.Coupon(r.getObject("id",UUID.class),r.getString("code"),r.getBoolean("active"),r.getInt("maximum_uses")-r.getInt("reserved_uses")-r.getInt("consumed_uses"),r.getLong("version"));}
 private PromotionValues.Campaign campaign(ResultSet r)throws SQLException{return new PromotionValues.Campaign(r.getObject("id",UUID.class),r.getString("code"),r.getObject("rule_id",UUID.class),r.getObject("market_id",UUID.class),r.getInt("daily_limit"),r.getBigDecimal("reward_budget").setScale(2).toPlainString(),EventCodec.JSON.readTree(r.getString("outcomes")),r.getBoolean("enabled"),r.getLong("version"));}
 PromotionValues.Rule rule(UUID id,boolean lock){var rows=jdbc.query("SELECT * FROM commerce.promotion_rule WHERE id=?"+(lock?" FOR UPDATE":""),(r,n)->rule(r),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 PromotionValues.Rule create(PromotionValues.RuleInput in,String actor){family(in.code());if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.promotion_rule WHERE code=?)",Boolean.class,in.code())))throw new Problem.Failure(ProblemCode.CONFLICT);market(in.marketId());UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.promotion_rule(id,created_by,updated_by,code,revision,kind,market_id,starts_at,ends_at,parameters,eligibility,stacking_policy,enabled) VALUES (?,?,?, ?,1,?,?,?, ?,?::jsonb,?::jsonb,?,false)",id,actor,actor,in.code(),in.kind(),in.marketId(),Timestamp.from(in.startsAt()),Timestamp.from(in.endsAt()),EventCodec.JSON.writeValueAsString(in.parameters()),EventCodec.JSON.writeValueAsString(in.eligibility()),in.stackingPolicy());return rule(id,false);}
 PromotionValues.Rule revise(UUID id,long expected,PromotionValues.RuleInput in,String actor){var original=rule(id,false);family(original.code());var before=rule(id,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);Long latest=jdbc.queryForObject("SELECT max(revision) FROM commerce.promotion_rule WHERE code=?",Long.class,before.code());if(before.revision()!=latest||latest==Long.MAX_VALUE)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!in.marketId().equals(before.marketId()))market(in.marketId());else market(in.marketId());UUID next=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.promotion_rule(id,created_by,updated_by,code,revision,kind,market_id,starts_at,ends_at,parameters,eligibility,stacking_policy,enabled) VALUES (?,?,?, ?,?,?,?,?,?,?::jsonb,?::jsonb,?,false)",next,actor,actor,before.code(),latest+1,in.kind(),in.marketId(),Timestamp.from(in.startsAt()),Timestamp.from(in.endsAt()),EventCodec.JSON.writeValueAsString(in.parameters()),EventCodec.JSON.writeValueAsString(in.eligibility()),in.stackingPolicy());return rule(next,false);}
 PromotionValues.Page<PromotionValues.Rule> rules(PromotionValues.Query q){return page("promotion_rule",q,(r,n)->rule(r));}
 PromotionValues.Coupon createCoupon(PromotionValues.CouponInput in,String actor){var r=rule(in.ruleId(),true);if(!r.endsAt().isAfter(clock.instant())||!in.expiresAt().isAfter(clock.instant())||in.expiresAt().isAfter(r.endsAt()))throw PromotionValues.rule();UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.coupon(id,created_by,updated_by,rule_id,code,party_id,maximum_uses,maximum_uses_per_party,expires_at,active) VALUES (?,?,?,?,?,?,?,?,?,false)",id,actor,actor,in.ruleId(),in.code(),in.partyId(),in.maximumUses(),in.maximumUsesPerParty(),Timestamp.from(in.expiresAt()));return coupon(id,false);}
 PromotionValues.Coupon coupon(UUID id,boolean lock){var rows=jdbc.query("SELECT * FROM commerce.coupon WHERE id=?"+(lock?" FOR UPDATE":""),(r,n)->coupon(r),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 PromotionValues.Coupon toggleCoupon(UUID id,long expected,boolean active,String actor){var c=coupon(id,true);if(c.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(c.version()==Long.MAX_VALUE)throw PromotionValues.rule();if(active){var rules=jdbc.queryForList("SELECT r.id,r.enabled AS rule_enabled,r.starts_at,r.ends_at,m.enabled AS market_enabled FROM commerce.coupon c JOIN commerce.promotion_rule r ON r.id=c.rule_id JOIN commerce.market m ON m.id=r.market_id WHERE c.id=? FOR SHARE OF c,r,m",id);if(rules.size()!=1||!Boolean.TRUE.equals(rules.getFirst().get("rule_enabled"))||!Boolean.TRUE.equals(rules.getFirst().get("market_enabled"))||((Timestamp)rules.getFirst().get("starts_at")).toInstant().isAfter(clock.instant())||!((Timestamp)rules.getFirst().get("ends_at")).toInstant().isAfter(clock.instant()))throw PromotionValues.rule();var approval=jdbc.query("SELECT value::text,approved_by FROM commerce.feature_configuration WHERE key=? AND active FOR SHARE",(r,n)->new Object[]{r.getString(1),r.getString(2)},"PROMOTION_COUPON_"+id);if(approval.size()!=1||approval.getFirst()[1]==null)throw PromotionValues.rule();JsonNode value=EventCodec.JSON.readTree((String)approval.getFirst()[0]);var detail=jdbc.queryForMap("SELECT rule_id,maximum_uses,maximum_uses_per_party,expires_at FROM commerce.coupon WHERE id=?",id);if(!id.toString().equals(value.path("couponId").asString())||!detail.get("rule_id").toString().equals(value.path("ruleId").asString())||((Number)detail.get("maximum_uses")).intValue()!=value.path("maximumUses").asInt(-1)||((Number)detail.get("maximum_uses_per_party")).intValue()!=value.path("maximumUsesPerParty").asInt(-1)||!((Timestamp)detail.get("expires_at")).toInstant().toString().equals(value.path("expiresAt").asString())||!value.path("enabled").asBoolean(false))throw PromotionValues.rule();}jdbc.update("UPDATE commerce.coupon SET active=?,version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=?",active,Timestamp.from(clock.instant()),actor,id,expected);return coupon(id,false);}
 PromotionValues.Page<PromotionValues.Coupon> coupons(PromotionValues.Query q){return page("coupon",q,(r,n)->coupon(r));}
 PromotionValues.Campaign createCampaign(PromotionValues.CampaignInput in,String actor){var r=rule(in.ruleId(),true);if(!r.enabled()||!r.marketId().equals(in.marketId()))throw PromotionValues.rule();market(in.marketId());UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.wheel_campaign(id,created_by,updated_by,rule_id,market_id,code,daily_limit,reward_budget,enabled) VALUES (?,?,?,?,?,?,?,?::numeric,false)",id,actor,actor,in.ruleId(),in.marketId(),in.code(),in.dailyLimit(),in.rewardBudget());for(var o:in.outcomes())jdbc.update("INSERT INTO commerce.wheel_outcome(id,created_by,updated_by,campaign_id,label,kind,weight,benefit) VALUES (?,?,?,?,?,?,?,?::jsonb)",EventCodec.uuid7(clock.instant()),actor,actor,id,o.label(),o.kind(),o.weight(),EventCodec.JSON.writeValueAsString(o.benefit()));return campaign(id,false);}
 PromotionValues.Campaign campaign(UUID id,boolean lock){if(lock){var locked=jdbc.queryForList("SELECT id FROM commerce.wheel_campaign WHERE id=? FOR UPDATE",id);if(locked.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);}var rows=jdbc.query("SELECT c.*,coalesce(jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'kind',o.kind,'weight',o.weight,'benefit',o.benefit) ORDER BY o.id) FILTER (WHERE o.id IS NOT NULL),'[]'::jsonb)::text AS outcomes FROM commerce.wheel_campaign c LEFT JOIN commerce.wheel_outcome o ON o.campaign_id=c.id WHERE c.id=? GROUP BY c.id",(r,n)->campaign(r),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 PromotionValues.Campaign toggleCampaign(UUID id,long expected,boolean enabled,String actor){var c=campaign(id,true);if(c.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(enabled){if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.promotion_rule r JOIN commerce.market m ON m.id=r.market_id WHERE r.id=? AND r.enabled AND r.starts_at<=? AND r.ends_at>? AND m.enabled AND m.code='NG' AND m.currency_code='NGN')",Boolean.class,c.ruleId(),Timestamp.from(clock.instant()),Timestamp.from(clock.instant()))))throw PromotionValues.rule();var approval=jdbc.query("SELECT value::text,approved_by FROM commerce.feature_configuration WHERE key=? AND active FOR SHARE",(r,n)->new Object[]{r.getString(1),r.getString(2)},"PROMOTION_CAMPAIGN_"+id);if(approval.size()!=1||approval.getFirst()[1]==null)throw PromotionValues.rule();JsonNode value=EventCodec.JSON.readTree((String)approval.getFirst()[0]);if(!id.toString().equals(value.path("campaignId").asString())||c.version()!=value.path("campaignVersion").asLong(-1)||!c.rewardBudget().equals(value.path("rewardBudget").asString())||c.dailyLimit()!=value.path("dailyLimit").asInt(-1)||!EventCodec.hash(c.outcomes()).equals(value.path("outcomesHash").asString())||!value.path("enabled").asBoolean(false))throw PromotionValues.rule();}if(c.version()==Long.MAX_VALUE)throw PromotionValues.rule();jdbc.update("UPDATE commerce.wheel_campaign SET enabled=?,version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=?",enabled,Timestamp.from(clock.instant()),actor,id,expected);return campaign(id,false);}
 PromotionValues.Page<PromotionValues.Campaign> campaigns(PromotionValues.Query q){String sort=switch(q.sort()){case "createdAt,asc"->"c.created_at ASC";case "code,asc"->"c.code ASC";case "code,desc"->"c.code DESC";default->"c.created_at DESC";};long total=jdbc.queryForObject("SELECT count(*) FROM commerce.wheel_campaign",Long.class);var values=jdbc.query("SELECT c.*,coalesce(jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'kind',o.kind,'weight',o.weight,'benefit',o.benefit) ORDER BY o.id) FILTER (WHERE o.id IS NOT NULL),'[]'::jsonb)::text AS outcomes FROM commerce.wheel_campaign c LEFT JOIN commerce.wheel_outcome o ON o.campaign_id=c.id GROUP BY c.id ORDER BY "+sort+",c.id LIMIT ? OFFSET ?",(r,n)->campaign(r),q.size(),(long)q.page()*q.size());return new PromotionValues.Page<>(values,q.page(),q.size(),total,Math.toIntExact((total+q.size()-1)/q.size()),q.sort());}
 PromotionValues.Draw draw(UUID campaignId,UUID party,UUID market,String requestKey,String actor){
  Instant now=clock.instant();LocalDate day=now.atZone(ZoneOffset.UTC).toLocalDate();jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(r,n)->1,"wheel-party:"+campaignId+":"+party+":"+day);
  var rows=jdbc.queryForList("SELECT id FROM commerce.wheel_campaign WHERE id=? FOR UPDATE",campaignId);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var campaignRows=jdbc.query("SELECT c.*,coalesce(jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'kind',o.kind,'weight',o.weight,'benefit',o.benefit) ORDER BY o.id) FILTER (WHERE o.id IS NOT NULL),'[]'::jsonb)::text AS outcomes FROM commerce.wheel_campaign c JOIN commerce.wheel_outcome o ON o.campaign_id=c.id WHERE c.id=? GROUP BY c.id",(r,n)->campaign(r),campaignId);if(campaignRows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var c=campaignRows.getFirst();if(!c.enabled()||!c.marketId().equals(market)||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.market WHERE id=? AND enabled AND code='NG' AND currency_code='NGN')",Boolean.class,market)))throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);
  if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.promotion_rule WHERE id=? AND enabled AND starts_at<=? AND ends_at>?)",Boolean.class,c.ruleId(),Timestamp.from(now),Timestamp.from(now))))throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);
  Integer number=jdbc.queryForObject("SELECT coalesce(max(draw_number),0)+1 FROM commerce.wheel_draw WHERE campaign_id=? AND party_id=? AND window_key=?",Integer.class,campaignId,party,java.sql.Date.valueOf(day));if(number==null||number>c.dailyLimit())throw PromotionValues.rule();if(number>1){String prior=jdbc.queryForObject("SELECT o.kind FROM commerce.wheel_draw d JOIN commerce.wheel_outcome o ON o.id=d.outcome_id WHERE d.campaign_id=? AND d.party_id=? AND d.window_key=? AND d.draw_number=?",String.class,campaignId,party,java.sql.Date.valueOf(day),number-1);if(!"RETRY".equals(prior))throw PromotionValues.rule();}JsonNode outcomes=c.outcomes();long total=0;for(JsonNode o:outcomes)total=Math.addExact(total,o.path("weight").longValue());long pick=RANDOM.nextLong(total);JsonNode selected=null;for(JsonNode o:outcomes){pick-=o.path("weight").longValue();if(pick<0){selected=o;break;}}if(selected==null)throw PromotionValues.rule();if("RETRY".equals(selected.path("kind").asString())&&selected.path("benefit").path("extraDraws").asInt()!=1)throw PromotionValues.rule();
  UUID outcomeId=ApiValues.uuid(selected.path("id").asString());String kind=selected.path("kind").asString();JsonNode benefit=selected.path("benefit");BigDecimal cost=BigDecimal.ZERO.setScale(2);if(Set.of("COUPON","FREE_DELIVERY").contains(kind))cost=new BigDecimal(benefit.path("maximumDiscount").asString()).setScale(2);BigDecimal budget=new BigDecimal(c.rewardBudget()),spent=jdbc.queryForObject("SELECT spent_budget FROM commerce.wheel_campaign WHERE id=?",BigDecimal.class,campaignId);if(spent==null||spent.add(cost).compareTo(budget)>0)throw PromotionValues.rule();
  String couponCode=null;UUID couponId=null;Instant expires=null;if(Set.of("COUPON","FREE_DELIVERY").contains(kind)){UUID ruleId=ApiValues.uuid(benefit.path("ruleId").asString());var ruleRows=jdbc.query("SELECT ends_at FROM commerce.promotion_rule WHERE id=? AND market_id=? AND enabled AND starts_at<=? AND ends_at>? FOR SHARE",(r,n)->r.getTimestamp(1).toInstant(),ruleId,market,Timestamp.from(now),Timestamp.from(now));if(ruleRows.size()!=1)throw PromotionValues.rule();expires=now.plusSeconds(benefit.path("expiresHours").intValue()*3600L);if(expires.isAfter(ruleRows.getFirst()))expires=ruleRows.getFirst();couponId=EventCodec.uuid7(now);couponCode="W"+UUID.randomUUID().toString().replace("-","").substring(0,30).toUpperCase(Locale.ROOT);jdbc.update("INSERT INTO commerce.coupon(id,created_by,updated_by,rule_id,code,party_id,maximum_uses,maximum_uses_per_party,expires_at,active) VALUES (?,?,?,?,?,?,1,1,?,true)",couponId,actor,actor,ruleId,couponCode,party,Timestamp.from(expires));}
  jdbc.update("UPDATE commerce.wheel_campaign SET spent_budget=spent_budget+?,version=version+1,updated_at=?,updated_by=? WHERE id=?",cost,Timestamp.from(now),actor,campaignId);UUID id=EventCodec.uuid7(now);jdbc.update("INSERT INTO commerce.wheel_draw(id,created_by,campaign_id,party_id,outcome_id,window_key,draw_number,coupon_id,request_key) VALUES (?,?,?,?,?,?,?,?,?)",id,actor,campaignId,party,outcomeId,java.sql.Date.valueOf(day),number,couponId,requestKey);return new PromotionValues.Draw(id,new PromotionValues.Outcome(selected.path("label").asString(),kind),couponCode,expires);
 }
 <T> PromotionValues.Page<T> page(String table,PromotionValues.Query q,org.springframework.jdbc.core.RowMapper<T> mapper){String sort=switch(q.sort()){case "createdAt,asc"->"created_at ASC";case "code,asc"->"code ASC";case "code,desc"->"code DESC";default->"created_at DESC";};long total=jdbc.queryForObject("SELECT count(*) FROM commerce."+table,Long.class);var values=jdbc.query("SELECT * FROM commerce."+table+" ORDER BY "+sort+",id LIMIT ? OFFSET ?",mapper,q.size(),(long)q.page()*q.size());return new PromotionValues.Page<>(values,q.page(),q.size(),total,Math.toIntExact((total+q.size()-1)/q.size()),q.sort());}
 private void market(UUID id){if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.market WHERE id=? AND code='NG' AND currency_code='NGN' AND enabled)",Boolean.class,id)))throw new Problem.Failure(ProblemCode.NOT_FOUND);}
}
